(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.3)*18 + Math.sin(x*0.02+t*0.32)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*8 + Math.sin(sx*0.018-t*0.38)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*70, 0.085, 2.4, 1.05]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * wt;
    hS += Math.sin(d*f*1.4 - t*sp*0.3 + 3.0) * wt * 0.5;
  }
  const n = src.length, act = aS/n, inh = iS/n, harm = hS/n;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8) + Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2
    + Math.sin(fx*0.06+fy*0.08-t*1.6)*0.15;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2 = Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.03-ang*5+t*0.8)*0.25;
  const sp3 = Math.sin(dist*0.12-ang*6+t*1.8)*0.15;
  const spiral = sp1 + sp2 + sp3;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral)*2.0);
  const rd2 = Math.tanh((harm*0.8 - act*0.5 + inh*0.3 + sp2*2.0)*1.8);
  const rdMix = Math.tanh((rd1 + rd2*0.6 + Math.sin(rd1*rd2*Math.PI*2)*0.3)*1.4);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15) + Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.25;
  const micro = Math.sin(fx*0.35+t*3)*Math.sin(fy*0.35-t*2.5)*0.12;
  const blend = rdMix*0.7 + cell*0.2 + micro*0.1, v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,78,118],[24,118,138],[45,155,140],
    [130,175,130],[195,185,90],[220,155,75],[210,110,65],[175,60,60],
    [120,30,55],[60,15,45],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(rdMix*Math.PI)*0.18;
  const edge = Math.abs(rdMix)>0.65 ? 1.0 + (Math.abs(rdMix)-0.65)*0.8 : 1.0;
  const glow = Math.max(0, 1.0-Math.abs(rdMix)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*55)|0)
  ];
}
